  class: net.officefloor.hq.app.role.RespondWithRole
# GET /api/sheets/{sheetId}/roles — the roles given on the sheet, by user name.
respond:
  class: net.officefloor.hq.app.role.RespondWithRoles
  govern: [ readonly-transaction ]
handle:
  class: net.officefloor.hq.app.role.HandleInvalidRole

