import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** The role a user name has on the sheet: clerk (any name not given one), steward or viewer (sees everything, changes nothing). */
export type Role = { sheetId: string; user: string; role: string };

export const rolesKey = (sheetId: string) => ['sheet', sheetId, 'roles'];

/** The roles given on the sheet, by user name. */
export function useRoles(sheetId: string) {
  return useQuery({
    queryKey: rolesKey(sheetId),
    queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { rolesKey, useRoles, type Role } from './roles';

/** The sheet's roles: the form that gives a user name a role (clerk, steward or viewer — a viewer sees everything and changes nothing), and every role given. */
function Roles({ sheetId, user }: { sheetId: string; user: string }) {
  const roles = useRoles(sheetId);
  const queryClient = useQueryClient();
  const [name, setName] = useState('');
  const [role, setRole] = useState('');

  const submit = useSubmitOnce();
  const save = useMutation({
    mutationFn: (v: { name: string; role: string }) =>
      putJson<Role>(`/api/sheets/${encodeURIComponent(sheetId)}/roles/${encodeURIComponent(v.name.trim())}`, {
        role: v.role,
        by: user,
      }),
    onSuccess: () => {
      setName('');
      setRole('');
      void queryClient.invalidateQueries({ queryKey: rolesKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <section data-testid="roles">
      <h3>Roles</h3>
      <form
        data-testid="role-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          save.reset();
          save.mutate({ name, role });
        }}
      >
        <label>
          User{' '}
          <input
            data-testid="role-form-user"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Role{' '}
          <input
            data-testid="role-form-role"
            list="role-choices"
            value={role}
            onChange={(e) => {
              setRole(e.target.value);
              save.reset();
            }}
          />
          <datalist id="role-choices">
            <option value="clerk" />
            <option value="steward" />
            <option value="viewer" />
          </datalist>
        </label>{' '}
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {save.isError && (
          <span data-testid="role-form-error">The user name must not be blank and the role must be clerk, steward or viewer.</span>
        )}
      </form>
      {roles.isError && <p data-testid="roles-load-error">Could not load roles.</p>}
      <table data-testid="roles-table">
        <tbody>
          {(roles.data ?? []).map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 7, Component: Roles });
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's content on the home screen. Rendered once a user is signed in and a sheet is
 * loaded; everything a contribution shows or changes belongs to `sheetId` and is done as `user`.
 */
export const SheetPage = defineSlot<{ sheetId: string; user: string }>('sheet.page');
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

