# POST /api/sheets/{sheetId}/periods — add a period: a name and a from and to date, both inclusive. An empty name,
# a date that is not yyyy-MM-dd, a to-date before the from-date, a name already on the sheet (case and outer spaces
# ignored) or dates overlapping another period of the sheet is a 400 and writes nothing. Responds 201 with the
# period as stored.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriod
  next: check
check:
  class: net.officefloor.hq.app.period.CheckNewPeriod
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.period.AddPeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriodCreated
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the name is not empty, the from and to dates are yyyy-MM-dd, and the to-date is not before the
 *  from-date. */
public class ValidatePeriod {
    public void validate(@RequestBody PeriodRequest request, Out<PeriodValues> values) throws InvalidPeriodException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPeriodException("A period needs a name");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (to.isBefore(from)) {
            throw new InvalidPeriodException("The to-date may not be before the from-date");
        }
        values.set(new PeriodValues(name, from, to, request.by() == null ? "" : request.by().trim()));
    }

    private static LocalDate date(String text, String which) throws InvalidPeriodException {
        try {
            return LocalDate.parse(text == null ? "" : text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a date yyyy-MM-dd");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class RespondWithPeriodCreated {
    public void respond(@Val Period period, PeriodRepository periods, ObjectResponse<ResponseEntity<PeriodResponse>> response) {
        response.send(new ResponseEntity<>(PeriodResponse.from(period, periods), HttpStatus.CREATED));
    }
}

